// variadic parameter definitions
  function f1(integer a...); // type of a is record of integer
  function f2(integer a[3]...); // type of a is record of integer[3]
  function f3(integer a, integer b...);
  function f4(integer a..., integer b...); // ERROR: two variadic parameters
  function f5(integer a..., integer b); // ERROR: variadic parameter is not at final position
  function f6(integer a := 10, integer b... := {1,2,3});
  external function printf(universal charstring format, any args ...);
  // invoking functions with variadic parameters
  f1(); // value of a: {}
  f1(1); // value of a: {1}
  f1(1,2,3); // value of a: {1,2,3}
  f3(); // ERROR: f3 requires a value for parameter a
  f3(100); // value of b: {}
  f3(100,1,2,3); // value of b: {1,2,3}
  f3(a := 10, b := {1,2,3}); // assignment notation
  f3(b := {1,2,3}, a := 10); // assignment notation
  f3(10, b := {1,2,3}); // mixed notation
  f6(); // value of a: 10, value of b: {1,2,3}
  f6(1); // value of a: 1, value of b: {1,2,3}
  f6(1,2); // value of a: 1, value of b: {2}
  f6(-) // value of a: 10, value of b: {1,2,3}
  f6(-,1) // value of a: 10, value of b: {1}
  f6(-,-) // value of a: 10, value of b: {1,2,3}
  f6(-,-,-) // ERROR: f6 has only two formal parameters to skip.
  var record of integer a := {1,2,3};
  f1(a...); // passing a record of parameter directly

